def transform(grid):
    h, w = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    bg = max(range(10), key=flat.count)

    # Uniform full-length lines in a color other than the background are dividers.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(n, divs):
        bounds = [-1] + divs + [n]
        return [(bounds[i] + 1, bounds[i+1]) for i in range(len(bounds)-1) if bounds[i+1] > bounds[i]+1]

    rows, cols = spans(h, div_rows), spans(w, div_cols)
    panels = [(r0,r1,c0,c1) for r0,r1 in rows for c0,c1 in cols]
    src = max(panels, key=lambda p: sum(grid[r][c] != bg for r in range(p[0],p[1]) for c in range(p[2],p[3])))
    pat = [row[src[2]:src[3]] for row in grid[src[0]:src[1]]]
    out = [row[:] for row in grid]
    for r0,r1,c0,c1 in panels:
        if r1-r0 != len(pat) or c1-c0 != len(pat[0]):
            continue
        for i in range(len(pat)):
            for j in range(len(pat[0])):
                out[r0+i][c0+j] = pat[i][j]
