g=[list(map(int,l.split())) for l in open('.openclaw/tmp/grid.txt')]
from collections import Counter
seen=set(); comps=[]
for r in range(30):
 for c in range(30):
  if g[r][c] and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c));p=[]
   while st:
    y,x=st.pop();p.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     ny,nx=y+dy,x+dx
     if 0<=ny<30 and 0<=nx<30 and g[ny][nx] and (ny,nx) not in seen:seen.add((ny,nx));st.append((ny,nx))
   comps.append(p)
for p in comps:
 y0=min(y for y,x in p);x0=min(x for y,x in p);h=max(y for y,x in p)-y0+1;w=max(x for y,x in p)-x0+1
 print(len(p),h,w, 'rect outline expected',2*h+2*w-4)
PY

