    out = [row[:] for row in grid]
    # Outside-reachable background cells define exterior versus enclosed cavities.
    seen = set()
    stack = [(r,c) for r in range(h) for c in range(w)
             if (r == 0 or c == 0 or r == h-1 or c == w-1) and grid[r][c] == 0]
    while stack:
        r,c=stack.pop()
        if (r,c) in seen or grid[r][c] != 0: continue
        seen.add((r,c))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in seen:
                stack.append((nr,nc))
    enclosed={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in seen}
